DROP TABLE IF EXISTS `metodologias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `metodologias` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `version` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1.0',
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `formula` text COLLATE utf8mb4_unicode_ci,
  `limitaciones` text COLLATE utf8mb4_unicode_ci,
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `activa` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_metodologias_nombre_version` (`nombre`,`version`),
  KEY `idx_metodologias_activa` (`activa`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `metodologias`
--

LOCK TABLES `metodologias` WRITE;
/*!40000 ALTER TABLE `metodologias` DISABLE KEYS */;
INSERT INTO `metodologias` VALUES (1,'Participación porcentual','1.0','Participación = (Votantes / Electores) × 100. Abstención = 100 - Participación.','(SV / LN) × 100','No contempla voto en casillas especiales ni mexicanas y mexicanos residentes en el extranjero.','2026-10-30 17:52:53',1),(2,'Variación histórica en puntos porcentuales','1.0','Variación = Participación final - Participación inicial. Se expresa en puntos porcentuales (pp), no en porcentaje relativo.','P_final - P_inicial','Solo válida entre elecciones con indicadores y territorios compatibles.','2026-10-30 17:52:53',1),(3,'Clasificación básica de perfiles','1.0','Reglas basadas en umbrales de nivel relativo y variación histórica.','Reglas condicionales sobre diferencia vs referencia y variación pp.','Umbrales definidos semialmente; requieren validación con análisis exploratorio.','2026-10-30 17:52:53',1);
/*!40000 ALTER TABLE `metodologias` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `participacion_electoral`
--

DROP TABLE IF EXISTS `participacion_electoral`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `participacion_electoral` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `eleccion_id` int NOT NULL,
  `territorio_id` bigint NOT NULL,
  `segmento_id` bigint NOT NULL,
  `fuente_id` bigint NOT NULL,
  `lote_importacion_id` bigint DEFAULT NULL,
  `electores` bigint NOT NULL DEFAULT '0' COMMENT 'Lista nominal / universo de referencia',
  `votantes` bigint NOT NULL DEFAULT '0' COMMENT 'Registros con marca de voto (SV)',
  `fecha_registro` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_participacion_eleccion_territorio_segmento` (`eleccion_id`,`territorio_id`,`segmento_id`),
  KEY `idx_participacion_eleccion` (`eleccion_id`),
  KEY `idx_participacion_territorio` (`territorio_id`),
  KEY `idx_participacion_segmento` (`segmento_id`),
  KEY `idx_participacion_fuente` (`fuente_id`),
  KEY `idx_participacion_consulta` (`eleccion_id`,`segmento_id`,`territorio_id`),
  CONSTRAINT `fk_participacion_eleccion` FOREIGN KEY (`eleccion_id`) REFERENCES `elecciones` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_participacion_fuente` FOREIGN KEY (`fuente_id`) REFERENCES `fuentes_datos` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_participacion_segmento` FOREIGN KEY (`segmento_id`) REFERENCES `segmentos_demograficos` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_participacion_territorio` FOREIGN KEY (`territorio_id`) REFERENCES `territorios` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_participacion_electores_no_negativo` CHECK ((`electores` >= 0)),
  CONSTRAINT `chk_participacion_votantes_menor_igual_electores` CHECK ((`votantes` <= `electores`)),
  CONSTRAINT `chk_participacion_votantes_no_negativo` CHECK ((`votantes` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Tabla central: conteos oficiales de electores y votantes por elección, territorio y segmento.';
/*!40101 SET character_set_client = @saved_cs_client */;

