INSERT INTO `perfiles` VALUES (1,'PERF-01','Participación alta respecto a la referencia','Participación al menos 5 pp por encima de la referencia nacional, sin cambio mayor de 3 pp cuando existe elección previa.',1,'2026-10-30 17:52:53'),(2,'PERF-02','Participación en crecimiento','Territorios con incremento relevante de participación entre elecciones.',1,'2026-10-30 17:52:53'),(3,'PERF-03','Participación en descenso','Territorios con disminución relevante de participación entre elecciones.',1,'2026-10-30 17:52:53'),(4,'PERF-04','Participación baja respecto a la referencia','Participación al menos 5 pp por debajo de la referencia nacional, sin crecimiento o descenso superior a 3 pp.',1,'2026-10-30 17:52:53'),(5,'PERF-05','Participación próxima a la referencia','Diferencia menor a 5 pp respecto a la referencia nacional, sin crecimiento o descenso superior a 3 pp.',1,'2026-10-30 17:52:53');
